  "c9_les_7_3": {
    id: "note_c9_les_7_3",
    classId: 9,
    themeId: "c9_theme_7",
    chapterId: "c9_theme_7",
    topicId: "c9_les_7_3",
    title: "Simple 2D Right Triangle Problems Involving Angles of Elevation/Depression Basics",
    category: "Geometry",
    color: "#d97706",
    bgLight: "#fef3c7",
    learningObjectives: [
      "Master the foundational concepts of Simple 2D Right Triangle Problems Involving Angles of Elevation/Depression Basics.",
      "Understand and apply governing rules and properties accurately.",
      "Solve standard Class 9 ICSE exam-style problems with step-by-step reasoning."
    ],
    keyConcepts: [
      { topic: "Core Definition", text: "BC = 20 × sin 30° = 10 cm." },
      { topic: "Governing Principle", text: "SI = (P × R × T) / 100 | Amount A = P(1 + R/100)ⁿ" }
    ],
    visualConcept: {
      title: "Simple 2D Right Triangle Problems Involving Angles of Elevation/Depression Basics Visual Representation",
      label: "SI = (P × R × T) / 100 | Amount A = P(1 + R/100)ⁿ",
      badges: ["Class 9 ICSE", "Geometry", "Syllabus Standard"]
    },
    workedExample: {
      problem: "In right-angled triangle ABC (∠B = 90°), if ∠A = 30° and hypotenuse AC = 20 cm, find BC (opposite side):",
      steps: [
        "Step 1: Write down the given mathematical parameters.",
        "Step 2: Apply the governing rule: SI = (P × R × T) / 100 | Amount A = P(1 + R/100)ⁿ.",
        "Step 3: Calculate the canonical result: 10 cm."
      ],
      answer: "10 cm"
    },
    tryIt: {
      question: "In the same triangle (AC = 20 cm, ∠A = 30°), find AB (adjacent side):",
      answer: "10√3 cm",
      hint: "AB = AC cos 30° = 20 × (√3/2) = 10√3 cm."
    },
    remember: "BC = AC sin 30° = 20 × ½ = 10 cm."
  },
  "c9_les_7_4": {
    id: "note_c9_les_7_4",
    classId: 9,
    themeId: "c9_theme_7",
    chapterId: "c9_theme_7",
    topicId: "c9_les_7_4",
    title: "Complementary Angles: sin(90°-θ) = cos θ, tan(90°-θ) = cot θ, sec(90°-θ) = cosec θ",
    category: "Trigonometry",
    color: "#d97706",
    bgLight: "#fef3c7",
    learningObjectives: [
      "Master the foundational concepts of Complementary Angles.",
      "Understand and apply governing rules and properties accurately.",
      "Solve standard Class 9 ICSE exam-style problems with step-by-step reasoning."
    ],
    keyConcepts: [
      { topic: "Core Definition", text: "sin (90° - θ) = cos θ." },
      { topic: "Governing Principle", text: "sin θ = Opp/Hyp | cos θ = Adj/Hyp | tan θ = Opp/Adj | sin²θ + cos²θ = 1" }
    ],
    visualConcept: {
      title: "Complementary Angles Visual Representation",
      label: "sin θ = Opp/Hyp | cos θ = Adj/Hyp | tan θ = Opp/Adj | sin²θ + cos²θ = 1",
      badges: ["Class 9 ICSE", "Trigonometry", "Syllabus Standard"]
    },
    workedExample: {
      problem: "What is sin (90° - θ) equal to?",
      steps: [
        "Step 1: Write down the given mathematical parameters.",
        "Step 2: Apply the governing rule: sin θ = Opp/Hyp | cos θ = Adj/Hyp | tan θ = Opp/Adj | sin²θ + cos²θ = 1.",
        "Step 3: Calculate the canonical result: cos θ."
      ],
      answer: "cos θ"
    },
    tryIt: {
      question: "What is tan (90° - θ) equal to?",
      answer: "cot θ",
      hint: "Co-function of tangent is cotangent."
    },
    remember: "Co-function identity: sin becomes cos."
  },
