  "c9_les_8_3": {
    id: "note_c9_les_8_3",
    classId: 9,
    themeId: "c9_theme_8",
    chapterId: "c9_theme_8",
    topicId: "c9_les_8_3",
    title: "Distance Formula: Distance Between Two Points on Coordinate Plane",
    category: "Trigonometry",
    color: "#d97706",
    bgLight: "#fef3c7",
    learningObjectives: [
      "Master the foundational concepts of Distance Formula.",
      "Understand and apply governing rules and properties accurately.",
      "Solve standard Class 9 ICSE exam-style problems with step-by-step reasoning."
    ],
    keyConcepts: [
      { topic: "Core Definition", text: "Distance d = √[ (x₂ - x₁)² + (y₂ - y₁)² ]." },
      { topic: "Governing Principle", text: "sin θ = Opp/Hyp | cos θ = Adj/Hyp | tan θ = Opp/Adj | sin²θ + cos²θ = 1" }
    ],
    visualConcept: {
      title: "Distance Formula Visual Representation",
      label: "sin θ = Opp/Hyp | cos θ = Adj/Hyp | tan θ = Opp/Adj | sin²θ + cos²θ = 1",
      badges: ["Class 9 ICSE", "Trigonometry", "Syllabus Standard"]
    },
    workedExample: {
      problem: "What is the DISTANCE FORMULA between points P(x₁, y₁) and Q(x₂, y₂)?",
      steps: [
        "Step 1: Write down the given mathematical parameters.",
        "Step 2: Apply the governing rule: sin θ = Opp/Hyp | cos θ = Adj/Hyp | tan θ = Opp/Adj | sin²θ + cos²θ = 1.",
        "Step 3: Calculate the canonical result: d = √[ (x₂ - x₁)² + (y₂ - y₁)² ]."
      ],
      answer: "d = √[ (x₂ - x₁)² + (y₂ - y₁)² ]"
    },
    tryIt: {
      question: "What is the distance of the point P(x, y) from the ORIGIN (0, 0)?",
      answer: "d = √(x² + y²)",
      hint: "Origin is (0,0): √((x-0)² + (y-0)²)."
    },
    remember: "Derived from Pythagoras theorem."
  },

