  "c10_les_1_1": {
    id: "note_c10_les_1_1",
    classId: 10,
    themeId: "c10_theme_1",
    chapterId: "c10_theme_1",
    topicId: "c10_les_1_1",
    title: "Goods and Services Tax (GST) - CGST, SGST, IGST, Input/Output Tax Credit",
    category: "Commercial Mathematics",
    color: "#7c3aed",
    bgLight: "#f5f3ff",
    learningObjectives: [
      "Master the foundational concepts of Goods and Services Tax (GST) - CGST, SGST, IGST, Input/Output Tax Credit.",
      "Understand and apply governing rules and properties accurately.",
      "Solve standard Class 10 ICSE exam-style problems with step-by-step reasoning."
    ],
    keyConcepts: [
      { topic: "Core Definition", text: "For intra-state transactions, CGST = SGST = ½ of GST rate." },
      { topic: "Governing Principle", text: "Total GST = CGST + SGST (Intra-state) | IGST (Inter-state)" }
    ],
    visualConcept: {
      title: "Goods and Services Tax (GST) - CGST, SGST, IGST, Input/Output Tax Credit Visual Representation",
      label: "Total GST = CGST + SGST (Intra-state) | IGST (Inter-state)",
      badges: ["Class 10 ICSE", "Commercial Mathematics", "Syllabus Standard"]
    },
    workedExample: {
      problem: "For an INTRA-STATE sale (within same state), how is the total GST divided?",
      steps: [
        "Step 1: Write down the given mathematical parameters.",
        "Step 2: Apply the governing rule: Total GST = CGST + SGST (Intra-state) | IGST (Inter-state).",
        "Step 3: Calculate the canonical result: Equally between CGST and SGST (CGST = SGST = GST / 2)."
      ],
      answer: "Equally between CGST and SGST (CGST = SGST = GST / 2)"
    },
    tryIt: {
      question: "For an INTER-STATE sale (between two different states), which tax is levied?",
      answer: "IGST (Integrated GST)",
      hint: "Inter-state sales collect Integrated GST (IGST = full GST rate)."
    },
    remember: "Intra-state splits 50-50 between Central and State GST."
  },
  "c10_les_1_2": {
    id: "note_c10_les_1_2",
    classId: 10,
    themeId: "c10_theme_1",
    chapterId: "c10_theme_1",
    topicId: "c10_les_1_2",
    title: "Banking: Recurring Deposit (RD) Accounts & Maturity Value Calculation",
    category: "Commercial Mathematics",
    color: "#7c3aed",
    bgLight: "#f5f3ff",
    learningObjectives: [
      "Master the foundational concepts of Banking.",
      "Understand and apply governing rules and properties accurately.",
      "Solve standard Class 10 ICSE exam-style problems with step-by-step reasoning."
    ],
    keyConcepts: [
      { topic: "Core Definition", text: "I = P × [n(n + 1) / 24] × (R / 100)." },
      { topic: "Governing Principle", text: "SI = (P × R × T) / 100 | Amount A = P(1 + R/100)ⁿ" }
    ],
    visualConcept: {
      title: "Banking Visual Representation",
      label: "SI = (P × R × T) / 100 | Amount A = P(1 + R/100)ⁿ",
      badges: ["Class 10 ICSE", "Commercial Mathematics", "Syllabus Standard"]
    },
    workedExample: {
      problem: "What is the formula for calculating total INTEREST (I) in a Recurring Deposit (RD) account?",
      steps: [
        "Step 1: Write down the given mathematical parameters.",
        "Step 2: Apply the governing rule: SI = (P × R × T) / 100 | Amount A = P(1 + R/100)ⁿ.",
        "Step 3: Calculate the canonical result: I = P × [n(n + 1) / (2 × 12)] × (R / 100)."
      ],
      answer: "I = P × [n(n + 1) / (2 × 12)] × (R / 100)"
    },
    tryIt: {
      question: "What is the formula for the MATURITY VALUE (MV) of an RD account?",
      answer: "MV = (P × n) + I",
      hint: "Total monthly deposits + accumulated interest."
    },
    remember: "n is months. Total qualifying principal = P × n(n+1)/2 for 1 month."
  },
