  "c10_les_2_6": {
    id: "note_c10_les_2_6",
    classId: 10,
    themeId: "c10_theme_2",
    chapterId: "c10_theme_2",
    topicId: "c10_les_2_6",
    title: "Arithmetic and Geometric Progression (AP & GP, nth Term, Sum of n Terms)",
    category: "Algebra",
    color: "#7c3aed",
    bgLight: "#f5f3ff",
    learningObjectives: [
      "Master the foundational concepts of Arithmetic and Geometric Progression (AP & GP, nth Term, Sum of n Terms).",
      "Understand and apply governing rules and properties accurately.",
      "Solve standard Class 10 ICSE exam-style problems with step-by-step reasoning."
    ],
    keyConcepts: [
      { topic: "Core Definition", text: "Tₙ = a + (n - 1)d." },
      { topic: "Governing Principle", text: "SI = (P × R × T) / 100 | Amount A = P(1 + R/100)ⁿ" }
    ],
    visualConcept: {
      title: "Arithmetic and Geometric Progression (AP & GP, nth Term, Sum of n Terms) Visual Representation",
      label: "SI = (P × R × T) / 100 | Amount A = P(1 + R/100)ⁿ",
      badges: ["Class 10 ICSE", "Algebra", "Syllabus Standard"]
    },
    workedExample: {
      problem: "What is the formula for the nth term (Tₙ) of an ARITHMETIC PROGRESSION (AP)?",
      steps: [
        "Step 1: Write down the given mathematical parameters.",
        "Step 2: Apply the governing rule: SI = (P × R × T) / 100 | Amount A = P(1 + R/100)ⁿ.",
        "Step 3: Calculate the canonical result: Tₙ = a + (n - 1)d."
      ],
      answer: "Tₙ = a + (n - 1)d"
    },
    tryIt: {
      question: "What is the formula for the SUM of first n terms (Sₙ) of an AP?",
      answer: "Sₙ = (n / 2) [ 2a + (n - 1)d ] = (n / 2)(a + l)",
      hint: "n/2 × (first term + last term)."
    },
    remember: "a is first term, d is common difference."
  },
  "c10_les_2_7": {
    id: "note_c10_les_2_7",
    classId: 10,
    themeId: "c10_theme_2",
    chapterId: "c10_theme_2",
    topicId: "c10_les_2_7",
    title: "Coordinate Geometry: Reflection, Section Formula, Midpoint, Slope & Line Equation",
    category: "Algebra",
    color: "#7c3aed",
    bgLight: "#f5f3ff",
    learningObjectives: [
      "Master the foundational concepts of Coordinate Geometry.",
      "Understand and apply governing rules and properties accurately.",
      "Solve standard Class 10 ICSE exam-style problems with step-by-step reasoning."
    ],
    keyConcepts: [
      { topic: "Core Definition", text: "x = (mx₂ + nx₁)/(m + n) and y = (my₂ + ny₁)/(m + n)." },
      { topic: "Governing Principle", text: "Slope m = (y₂ - y₁) / (x₂ - x₁) | Line: y - y₁ = m(x - x₁)" }
    ],
    visualConcept: {
      title: "Coordinate Geometry Visual Representation",
      label: "Slope m = (y₂ - y₁) / (x₂ - x₁) | Line: y - y₁ = m(x - x₁)",
      badges: ["Class 10 ICSE", "Algebra", "Syllabus Standard"]
    },
    workedExample: {
      problem: "What is the SECTION FORMULA for internal division of segment joining (x₁, y₁) and (x₂, y₂) in ratio m : n?",
      steps: [
        "Step 1: Write down the given mathematical parameters.",
        "Step 2: Apply the governing rule: Slope m = (y₂ - y₁) / (x₂ - x₁) | Line: y - y₁ = m(x - x₁).",
        "Step 3: Calculate the canonical result: P = ( (mx₂ + nx₁)/(m + n), (my₂ + ny₁)/(m + n) )."
      ],
      answer: "P = ( (mx₂ + nx₁)/(m + n), (my₂ + ny₁)/(m + n) )"
    },
    tryIt: {
      question: "What is the formula for the SLOPE (gradient m) of a line passing through (x₁, y₁) and (x₂, y₂)?",
      answer: "m = (y₂ - y₁) / (x₂ - x₁) = tan θ",
      hint: "Rise over run: Δy / Δx."
    },
    remember: "Weighted average of endpoints."
  },
