        "Step 2: Apply the governing rule: SI = (P × R × T) / 100 | Amount A = P(1 + R/100)ⁿ.",
        "Step 3: Calculate the canonical result: If a line is drawn parallel to one side of a triangle intersecting other two sides, it divides the other two sides in the SAME RATIO."
