/**
 * Get interactive notes for a specific topic ID
 */
export const getInteractiveNotesForTopic = (topicId) => {
  if (!topicId) return null;
  return classInteractiveNotes[topicId] || null;
};

/**
 * Get all interactive notes for a chapter or class
 */
export const getInteractiveNotesForChapter = (chapterId, classId) => {
  const cNum = typeof classId === 'string' ? parseInt(classId.replace(/\D/g, ''), 10) : classId;
  return Object.values(classInteractiveNotes).filter(n => {
    const matchesClass = cNum ? n.classId === cNum : true;
    const matchesChap = chapterId ? n.chapterId === chapterId || n.themeId === chapterId || n.topicId.startsWith(chapterId.replace('chap_', 'les_')) : true;
    return matchesClass && matchesChap;
  });
};
